func (v OverlayValue) Equal(o attr.Value) bool {
	other, ok := o.(OverlayValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AdditionalSkills.Equal(other.AdditionalSkills) {
		return false
	}

	if !v.AdditionalTools.Equal(other.AdditionalTools) {
		return false
	}

	if !v.AllowedCollections.Equal(other.AllowedCollections) {
		return false
	}

	if !v.DisabledSkills.Equal(other.DisabledSkills) {
		return false
	}

	if !v.DisabledTools.Equal(other.DisabledTools) {
		return false
	}

	if !v.FilterPolicies.Equal(other.FilterPolicies) {
		return false
	}

	if !v.GuardrailPreset.Equal(other.GuardrailPreset) {
		return false
	}

	if !v.LongContext.Equal(other.LongContext) {
		return false
	}

	if !v.MaxTokens.Equal(other.MaxTokens) {
		return false
	}

	if !v.McpServers.Equal(other.McpServers) {
		return false
	}

	if !v.ModelId.Equal(other.ModelId) {
		return false
	}

	if !v.ReasoningEffort.Equal(other.ReasoningEffort) {
		return false
	}

	if !v.SystemPromptAppend.Equal(other.SystemPromptAppend) {
		return false
	}

	if !v.Temperature.Equal(other.Temperature) {
		return false
	}

	if !v.Version.Equal(other.Version) {
		return false
	}

	return true
}

func (v OverlayValue) Type(ctx context.Context) attr.Type {
	return OverlayType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

